def signals(history):
    candidates = []
    for ticker, bars in history.items():
        close = [bar["close"] for bar in bars]
        if len(close) >= 40:
            short = sum(close[-10:]) / 10
            long = sum(close[-40:]) / 40
            if short > long:
                candidates.append(ticker)
    return {ticker: 1.0 / len(candidates) for ticker in candidates} if candidates else {}

def signals(history):
    ticker = sorted(history)[0]
    close = [bar["close"] for bar in history[ticker]]
    if len(close) < 20:
        return {}
    center = sum(close[-20:]) / 20
    if close[-1] <= center * 0.975:
        weight = 1.0
    elif close[-1] >= center * 1.025:
        weight = 0.0
    else:
        weight = 0.5
    return {ticker: weight}

def signals(history):
    names = sorted(history)
    weights = {}
    for ticker in names:
        close = [b["close"] for b in history[ticker]]
        if len(close) < 61:
            continue
        ret60 = close[-1] / close[-61] - 1
        if ret60 > 0.02:
            weights[ticker] = 1.0 / len(names)
        elif ret60 < -0.02:
            weights[ticker] = -1.0 / len(names)
    return weights

import statistics

def signals(history):
    names = sorted(history)
    if len(names) < 2:
        return {}
    a, b = names[:2]
    a_close = [x["close"] for x in history[a]]
    b_close = [x["close"] for x in history[b]]
    if len(a_close) < 41:
        return {}
    ratio = [x/y for x,y in zip(a_close[-40:], b_close[-40:])]
    mean = statistics.mean(ratio)
    sigma = statistics.pstdev(ratio)
    z = (ratio[-1] - mean) / sigma if sigma > 1e-10 else 0
    if z > 1.2:
        return {a: -0.5, b: 0.5}
    if z < -1.2:
        return {a: 0.5, b: -0.5}
    return {}
